#!/bin/bash
# Stage A of scope 09's crispness question, on a pinned GPU outside Slurm.
# biggpu allows one job per user through Slurm, so this runs with nohup on a device
# the launcher has checked is free. Do not edit this file while it is running.
set -u
REPO=/home-mscluster/mmolefe/Playground/PhD/poe_repair_min
PY=/home-mscluster/mmolefe/miniforge3/envs/co3/bin/python
cd "$REPO" || exit 1
export APPTAINER_BIND=/datasets
export PYTHONPATH="$REPO"
export XFORMERS_DISABLED=1
export CUDA_VISIBLE_DEVICES="${CUDA_VISIBLE_DEVICES:-1}"

echo "=== clean tail k sweep ==="
echo "node        $(hostname)"
echo "device      $CUDA_VISIBLE_DEVICES"
echo "commit      $(git rev-parse --short HEAD)  dirty_files=$(git status --porcelain | wc -l)"
echo "started     $(date -u +%FT%TZ)"
echo "condition   adapter on denoising steps [0,k), frozen SDXL plain PoE on [k,50)"
echo "k           25 29 33 36 40 50   (50 = adapter on the whole path, the control)"
echo "sampler     DDIM 50 steps, guidance 7.5, eta 0, 1024 square"
echo "bars        per seed: DINOv2 distance to that seed's own joint-prompt render at least"
echo "            0.05 nearer than k=50, composition not lost; Laplacian reported, never a bar"
echo

# The references first, in their own process. The windowed sampler returns with the adapter
# enabled, so a plain-CFG render made after it in the same process carries the correction.
$PY scripts/clean_tail_k_sweep.py --references || { echo "FAILED: references"; exit 1; }

for NAME in v1_freeze_null_r16_s0_25_30k pool43_all50_40k pool43_all50_60k; do
  echo
  echo "=== $NAME : render  $(date -u +%FT%TZ) ==="
  $PY scripts/clean_tail_k_sweep.py --render "$NAME" || { echo "FAILED: render $NAME"; exit 1; }
  echo "=== $NAME : score   $(date -u +%FT%TZ) ==="
  $PY scripts/clean_tail_k_sweep.py --score "$NAME"  || { echo "FAILED: score $NAME"; exit 1; }
  echo "=== $NAME : sheet   $(date -u +%FT%TZ) ==="
  $PY scripts/clean_tail_k_sweep.py --sheet "$NAME"  || { echo "FAILED: sheet $NAME"; exit 1; }
done

echo
echo "finished    $(date -u +%FT%TZ)"
